from scipy.optimize import least_squares
def fitf(f,p0,n=20):
    best=None
    for s in range(n):
        x0=np.array(p0,dtype=float)*np.exp(np.random.randn(len(p0))*0.5)
        try:
            r=least_squares(lambda p: f(p)-dP_dt, x0, max_nfev=3000)
            if np.isfinite(r.cost) and (best is None or r.cost<best.cost): best=r
        except Exception: pass
    return 2*best.cost/np.sum((dP_dt-dP_dt.mean())**2), np.round(best.x,4)
